import Foundation

/// Mirrors config/platforms.js (with each platform's `ios` overrides applied).
/// The bundled platforms.json is generated by `npm run ios:config`.
struct AdvanceStep: Codable {
    let type: String
    let selector: String?
    let key: String?
    let block: String?
    let tries: Int?
}

struct Platform: Codable {
    let id: String
    let name: String
    let enabled: Bool?
    let defaultOn: Bool?
    let feedUrl: String
    let loginUrl: String?
    let cookieDomains: [String]?
    let itemSelector: String?
    let advance: [AdvanceStep]?
    let verifyMs: Int?
}

struct InputConfig: Codable {
    let swipeMinPx: Double?
    let cooldownMs: Double?
}

struct AppConfig: Codable {
    let platforms: [Platform]
    let input: InputConfig?

    static func load() -> AppConfig {
        guard
            let url = Bundle.main.url(forResource: "platforms", withExtension: "json"),
            let data = try? Data(contentsOf: url),
            let config = try? JSONDecoder().decode(AppConfig.self, from: data)
        else {
            fatalError("platforms.json is missing or invalid. Run `npm run ios:config`.")
        }
        return AppConfig(platforms: config.platforms.filter { $0.enabled != false }, input: config.input)
    }
}
